package net.civeira.phylax.feature.observe.observedslo.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.valueobject.RouteVO;

@RequiredArgsConstructor
public class RouteValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<RouteVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getRoute() {
    return value.flatMap(RouteVO::getRoute);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<RouteVO> getRouteValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public RouteVO readRoute(final Optional<ObservedSlo> original, final ConstraintFailList fails) {
    return value.orElse(original.map(ObservedSlo::getRouteValue).orElseGet(RouteVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param route
   * @return
   */
  public T route(RouteVO route) {
    this.value = Optional.of(route);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param route
   * @return
   */
  public T route(Optional<RouteVO> route) {
    this.value = route;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param route
   * @return
   */
  public T route(String route) {
    this.value = Optional.of(RouteVO.from(route));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T routeNull() {
    this.value = Optional.of(RouteVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetRoute() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetRouteIfMatches(final String field) {
    if ("route".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
